import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './contexts/AuthContext';
import { Spinner } from '@heroui/react';
import PropTypes from 'prop-types';

import ProtectedRoute from './components/auth/ProtectedRoute';
import MainLayout from './components/layout/MainLayout';

import HomePage from './pages/HomePage';
import LoginPage from './pages/LoginPage';
import DashboardPage from './pages/DashboardPage';
import RecordPage from './pages/RecordPage';
import MeetingsPage from './pages/MeetingsPage';
import MeetingDetailPage from './pages/MeetingDetailPage';
import CalendarPage from './pages/CalendarPage';
import SettingsPage from './pages/SettingsPage';
import NotFoundPage from './pages/NotFoundPage';
import Tasks from './pages/Tasks';
import Decisions from './pages/Decisions';
import Analytics from './pages/Analytics';
import SpeakerCoachPage from './pages/SpeakerCoachPage';
import PublicMeetingSummary from './pages/PublicMeetingSummary';
import WorkspacesPage from './pages/WorkspacesPage';
import WorkspaceDetailPage from './pages/WorkspaceDetailPage';
import WorkspaceMeetingDetail from './pages/WorkspaceMeetingDetail';

const PublicRoute = ({ children }) => {
  const { isAuthenticated, loading } = useAuth();

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Spinner size="lg" label="Loading..." color="primary" />
      </div>
    );
  }

  if (isAuthenticated) {
    return <Navigate to="/dashboard" replace />;
  }

  return children;
};

PublicRoute.propTypes = {
  children: PropTypes.node.isRequired,
};

const AppRoutes = () => {
  return (
    <Routes>
      {}
      <Route path="/" element={<HomePage />} />
      <Route path="/share/:token" element={<PublicMeetingSummary />} />
      <Route
        path="/login"
        element={
          <PublicRoute>
            <LoginPage />
          </PublicRoute>
        }
      />

      {}
      <Route
        path="/dashboard"
        element={
          <ProtectedRoute>
            <MainLayout>
              <DashboardPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/record"
        element={
          <ProtectedRoute>
            <MainLayout>
              <RecordPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/calendar"
        element={
          <ProtectedRoute>
            <MainLayout>
              <CalendarPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/meetings"
        element={
          <ProtectedRoute>
            <MainLayout>
              <MeetingsPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/meeting/:id"
        element={
          <ProtectedRoute>
            <MainLayout>
              <MeetingDetailPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/settings"
        element={
          <ProtectedRoute>
            <MainLayout>
              <SettingsPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/decisions"
        element={
          <ProtectedRoute>
            <MainLayout>
              <Decisions />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/tasks"
        element={
          <ProtectedRoute>
            <MainLayout>
              <Tasks />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/analytics"
        element={
          <ProtectedRoute>
            <MainLayout>
              <Analytics />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/speaker-coach"
        element={
          <ProtectedRoute>
            <MainLayout>
              <SpeakerCoachPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/workspaces"
        element={
          <ProtectedRoute>
            <MainLayout>
              <WorkspacesPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/workspaces/:id"
        element={
          <ProtectedRoute>
            <MainLayout>
              <WorkspaceDetailPage />
            </MainLayout>
          </ProtectedRoute>
        }
      />
      <Route
        path="/workspaces/:id/meeting/:meetingId"
        element={
          <ProtectedRoute>
            <MainLayout>
              <WorkspaceMeetingDetail />
            </MainLayout>
          </ProtectedRoute>
        }
      />

      {}
      <Route path="/about" element={<NotFoundPage />} />
      <Route path="/privacy" element={<NotFoundPage />} />
      <Route path="/terms" element={<NotFoundPage />} />
      <Route path="/contact" element={<NotFoundPage />} />
      <Route path="/docs" element={<NotFoundPage />} />
      <Route path="/faq" element={<NotFoundPage />} />
      <Route path="/help" element={<NotFoundPage />} />
      <Route path="/features" element={<NotFoundPage />} />
      <Route path="/pricing" element={<NotFoundPage />} />

      {}
      <Route path="*" element={<NotFoundPage />} />
    </Routes>
  );
};

export default AppRoutes;
